G = {}

def load():
    import os, re
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        key_name, h, w = m[1], int(m[2]), int(m[3])
        if 'Demo pair' not in m[1]:
            continue
        content = t[m.end():]
        lines = [l.strip() for l in content.split('\n')[:h]]
        rows = [[int(x) for x in line.split()] for line in lines]
        G[key_name] = np.array(rows)
    return G

